CREATE TABLE `agents` (`id` uuid NOT NULL, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `name` text NOT NULL, `description` text NULL, `instructions` text NOT NULL, `builtin` bool NOT NULL DEFAULT (false), `model_id` uuid NULL, PRIMARY KEY (`id`), CONSTRAINT `agents_models_model` FOREIGN KEY (`model_id`) REFERENCES `models` (`id`) ON DELETE SET NULL);
CREATE TABLE `messages` (`id` uuid NOT NULL, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `source` text NOT NULL, `content` json NOT NULL, `usage` json NULL, `processed_time` datetime NULL, `task_id` uuid NOT NULL, `agent_id` uuid NULL, `model_id` uuid NULL, PRIMARY KEY (`id`), CONSTRAINT `messages_tasks_task` FOREIGN KEY (`task_id`) REFERENCES `tasks` (`id`) ON DELETE CASCADE, CONSTRAINT `messages_agents_agent` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE SET NULL, CONSTRAINT `messages_models_model` FOREIGN KEY (`model_id`) REFERENCES `models` (`id`) ON DELETE SET NULL, CONSTRAINT `agent_model` CHECK (agent_id IS NULL OR agent_id IS NOT NULL AND model_id IS NOT NULL));
CREATE TABLE `model_providers` (`id` uuid NOT NULL, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `name` text NOT NULL, `provider_type` text NOT NULL, `url` text NULL, `secret` blob NOT NULL, `enabled` bool NOT NULL DEFAULT (true), PRIMARY KEY (`id`));
CREATE TABLE `models` (`id` uuid NOT NULL, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `name` text NOT NULL, `context_window` integer NOT NULL, `capabilities` json NULL, `input_cost` real NOT NULL DEFAULT (0), `output_cost` real NOT NULL DEFAULT (0), `cache_write_cost` real NOT NULL DEFAULT (0), `cache_read_cost` real NOT NULL DEFAULT (0), `enabled` bool NOT NULL DEFAULT (true), `alias` text NULL, `model_provider_id` uuid NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `models_model_providers_models` FOREIGN KEY (`model_provider_id`) REFERENCES `model_providers` (`id`) ON DELETE NO ACTION);
CREATE TABLE `tasks` (`id` uuid NOT NULL, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `project_directory` text NULL, `input_tokens` integer NULL, `output_tokens` integer NULL, `cache_write_tokens` integer NULL, `cache_read_tokens` integer NULL, `cost` real NULL, `turns` integer NOT NULL DEFAULT (0), `tool_uses` json NOT NULL, `desired_phase` text NOT NULL DEFAULT ('running'), `phase` text NOT NULL DEFAULT ('awaiting'), `description` text NULL, `agent_id` uuid NULL, PRIMARY KEY (`id`), CONSTRAINT `tasks_agents_agent` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE SET NULL);
CREATE TABLE `tokens` (`id` uuid NOT NULL, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `name` text NOT NULL, `type` text NOT NULL DEFAULT ('api_token'), `token_hash` blob NOT NULL, `description` text NULL, `expires_at` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE UNIQUE INDEX `agent_name` ON `agents` (`name`);
CREATE INDEX `message_create_time` ON `messages` (`create_time`);
CREATE INDEX `message_task_id` ON `messages` (`task_id`);
CREATE INDEX `message_update_time` ON `messages` (`update_time`);
CREATE UNIQUE INDEX `model_name_model_provider_id` ON `models` (`name`, `model_provider_id`);
CREATE INDEX `task_create_time` ON `tasks` (`create_time`);
CREATE INDEX `task_update_time` ON `tasks` (`update_time`);
CREATE UNIQUE INDEX `token_name` ON `tokens` (`name`);
CREATE UNIQUE INDEX `token_token_hash` ON `tokens` (`token_hash`);
